int loadFile(std::string filepath, byte* &data)
{
    std::ifstream file(filepath, std::ios::binary | std::ios::ate);

    if (!file.is_open()) {
        std::cerr << "Error opening file!" << std::endl;
        return 0;
    }

    std::streamsize size = file.tellg();
    file.seekg(0, std::ios::beg);

    data = new byte[size];

    if (size > 8 && file.read((char*)data, size)) {
        std::cout << "Loaded file: " << filepath << std::endl;
    }
    else {
        std::cerr << "Error reading file!" << std::endl;
        return 0;
    }

    file.close();

    return size;
}

int loadR08(std::string filepath, ushort* &inputs, bool* &resets)
{
    byte* TAS;
    int size = loadFile(filepath, TAS);
    if (!size) return 0;

    inputs = (ushort*)TAS;
    resets = new bool[size / 2];

	return size / 2;
}

int loadBK2(std::string filepath, ushort*& inputs, bool*& resets)
{
    ZipArchive::Ptr archive = ZipFile::Open(filepath);
    ZipArchiveEntry::Ptr entry = archive->GetEntry("Input Log.txt");
    if (entry->IsPasswordProtected()) return 0;

    std::istream* decompressStream = entry->GetDecompressionStream();

    std::string line;

    std::vector<ushort> vInputs;
    std::vector<bool> vResets;

    int len;

    while (std::getline(*decompressStream, line))
    {
        if (line.at(0) != '|') continue;

        std::stringstream ss(line);
        std::string token;
        int i = 0;

        ushort input = 0;
        bool reset = false;

        while (std::getline(ss, token, '|'))
        {
            if (i > 1)
            {
                ushort b = 0;

                for (int c = 0; c < token.size(); c++)
                {
                    switch (token.at(c))
                    {
                    case 'A': b |= 0x80; break;
                    case 'B': b |= 0x40; break;
                    case 's': b |= 0x20; break;
                    case 'S': b |= 0x10; break;
                    case 'U': b |= 0x08; break;
                    case 'D': b |= 0x04; break;
                    case 'L': b |= 0x02; break;
                    case 'R': b |= 0x01; break;
                    default:  b |= 0x00; break;
                    }
                }

                if (i == 3) b <<= 8;
                input |= b;
            }
            else if (i == 1)
            {
                for (int c = 0; c < token.size(); c++)
                {
                    switch (token.at(c))
                    {
                    case 'r': reset = true; break;
                    default: break;
                    }
                }
            }

            i++;
        }

        vInputs.push_back(input);
        vResets.push_back(reset);

        len++;
    }

    inputs = new ushort[len];
    resets = new bool[len];

    for (int i = 0; i < len; i++)
    {
        inputs[i] = vInputs[i];
        resets[i] = vResets[i];
    }

    SetDropdownSelected(tasCPUSelect, BTN_TASCPU8);
    SetDropdownSelected(tasRAMSelect, BTN_TASRAM1);
    
    return len;
}

int loadFM2(std::string filepath, ushort*& inputs, bool*& resets)
{
    byte* TAS;
    int size = loadFile(filepath, TAS);
    if (!size) return 0;

    std::vector<ushort> vInputs;
    std::vector<bool> vResets;

    bool port0 = false;
    bool port1 = false;
    bool binary = false;

    int length = 0;
    int offset = 0;

    std::stringstream ss((char*)TAS);
    std::string line;

    while (std::getline(ss, line, '\n'))
    {
        if (line.at(0) == '|') break;

        offset += line.size() + 1;

        size_t space = line.find_first_of(" ");

        if (line.find("port0") == 0 && line.at(space + 1) == '1') port0 = true;
        if (line.find("port1") == 0 && line.at(space + 1) == '1') port1 = true;
        if (line.find("binary") == 0 && line.at(space + 1) == '1') binary = true;

        if (line.find("length") == 0)
        {
            std::string len = line.substr(space + 1, line.size());

            length = stoi(len);
        }
    }

    int len = 0;

    auto Flip = [](byte b) -> byte
        {
            b = (byte)(((b & 0xF0) >> 4) | ((b & 0xF) << 4));
            b = (byte)(((b & 0xCC) >> 2) | ((b & 0x33) << 2));
            b = (byte)(((b & 0xAA) >> 1) | ((b & 0x55) << 1));
            return b;
        };

    if (binary)
    {
        offset++;

        int stride = 1;

        if (port0) stride++;
        if (port1) stride++;

        int end = (length == 0) ? size : (offset + length * stride);

        int i = offset;

        while (i < end)
        {
            byte cmd = TAS[i++];
            byte pt0 = port0 ? TAS[i++] : 0x00;
            byte pt1 = port1 ? TAS[i++] : 0x00;

            vInputs.push_back((Flip(pt1) << 8) | Flip(pt0));
            vResets.push_back((cmd & 1) == 1);

            len++;
        }
    }
    else
    {
        ss = std::stringstream((char*)(&TAS[offset]));

        while (std::getline(ss, line, '\n'))
        {
            if (line.at(0) != '|') continue;

            std::stringstream ss2(line);
            std::string token;
            int i = 0;

            ushort input = 0;
            bool reset = false;

            while (std::getline(ss2, token, '|'))
            {
                if (i > 1)
                {
                    ushort b = 0;

                    for (int c = 0; c < token.size(); c++)
                    {
                        switch (token.at(c))
                        {
                        case 'A': b |= 0x80; break;
                        case 'B': b |= 0x40; break;
                        case 'S': b |= 0x20; break;
                        case 'T': b |= 0x10; break;
                        case 'U': b |= 0x08; break;
                        case 'D': b |= 0x04; break;
                        case 'L': b |= 0x02; break;
                        case 'R': b |= 0x01; break;
                        default:  b |= 0x00; break;
                        }
                    }

                    if (i == 3) b <<= 8;
                    input |= b;
                }
                else if (i == 1)
                {
                    int cmd = stoi(token);

                    reset = (cmd & 1) == 1;
                }

                i++;
            }

            vInputs.push_back(input);
            vResets.push_back(reset);

            len++;
        }
    }

    inputs = new ushort[len];
    resets = new bool[len];

    for (int i = 0; i < len; i++)
    {
        inputs[i] = vInputs[i];
        resets[i] = vResets[i];
    }

    SetMenuItemChecked(tas, BTN_FRAME0, true);

    return len;
}

int loadFMV(std::string filepath, ushort*& inputs, bool*& resets)
{
    byte* TAS;
    int size = loadFile(filepath, TAS);
    if (!size) return 0;

    std::vector<ushort> vInputs;
    std::vector<bool> vResets;

    // Famtasia: SsABDULR
    // TriCNES:  ABsSUDLR

    auto Fix = [](byte b) -> byte
        {
            b = (b & 0b11110011) | ((b & 0b00001000) >> 1) | ((b & 0b00000100) << 1);
            b = (b & 0b01101111) | ((b & 0b10000000) >> 3) | ((b & 0b00010000) << 3);
            b = (b & 0b10011111) | ((b & 0b01000000) >> 1) | ((b & 0b00100000) << 1);
            b = (b & 0b00111111) | ((b & 0b10000000) >> 1) | ((b & 0b01000000) << 1);
            return b;
        };

    bool port2 = (TAS[5] & 0b00010000) != 0;
    int len = 0;

    int i = 0x90;

    while (i < size)
    {
        vInputs.push_back(((port2 ? Fix(TAS[i++]) : 0x00) << 8) | Fix(TAS[i++]));
        vResets.push_back(false);

        len++;
    }

    inputs = new ushort[len];
    resets = new bool[len];

    for (int i = 0; i < len; i++)
    {
        inputs[i] = vInputs[i];
        resets[i] = vResets[i];
    }

    return len;
}

int load3C2(std::string filepath, ushort*& inputs, bool*& resets, bool c3)
{
    byte* TAS;
    int size = loadFile(filepath, TAS);
    if (!size) return 0;

    std::vector<ushort> vInputs;
    std::vector<bool> vResets;

    int i = c3 ? 15 : 0;

    int frames = c3 ? (TAS[8] | (TAS[9] << 8) | (TAS[10] << 16) | (TAS[11] << 24)) : 0;
    byte header = TAS[i++];

    bool port2 = (header & 2) != 0;
    bool reset = ((header & 4) != 0) || c3; // The byte still exists regardless in .3c3 format

    int len = 0;
    int stride = 1;

    if (port2) stride++;
    if (reset) stride++;

    int end = c3 ? (16 + frames * stride) : size;

    while (i < end)
    {
        vInputs.push_back(TAS[i++] | ((port2 ? TAS[i++] : 0x00) << 8));
        vResets.push_back(reset ? ((TAS[i++] & 0x80) == 0x80) : false);

        len++;
    }

    inputs = new ushort[len];
    resets = new bool[len];

    for (int i = 0; i < len; i++)
    {
        inputs[i] = vInputs[i];
        resets[i] = vResets[i];
    }

    SetDropdownSelected(tasFilterSelect, ((header & 1) == 1) ? BTN_TASCLOCK : BTN_TASLATCH);

    return len;
}



static std::vector<TriCNES::Cartridge> TriCTASCarts;
static std::vector<int> TriCTASSwaps;
static std::vector<int> TriCTASIndices;
static int TriCTASCycles;
static int TriCTASIndex;
static bool TriCTASRunning = false;

int load3CT(std::string filepath)
{

    byte* TAS;
    int size = loadFile(filepath, TAS);
    if (!size) return 0;

    std::stringstream ss((char*)TAS);
    std::string line;

    TriCTASCarts = std::vector<TriCNES::Cartridge>();
    TriCTASSwaps = std::vector<int>();
    TriCTASIndices = std::vector<int>();

    int i = 0;
    int carts = 0;

    while (std::getline(ss, line))
    {
        if (i == 0)
        {
            carts = stoi(line);
        }
        else if (i > 0 && i <= carts)
        {
            size_t r = line.find_first_of("\r");

            std::string filepath = "./roms/" + ((r == std::string::npos) ? line : line.substr(0, r));

            TriCNES::Cartridge cart = TriCNES::Cartridge(filepath);

            if (cart.Name.empty())
            {
                Alert(window, "Error", ("Could not load ROM:\n" + filepath).c_str(), dummy_handler);
                return 0;
            }

            TriCTASCarts.push_back(cart);
        }
        else
        {
            size_t space = line.find_first_of(" ");

            std::string cycle = line.substr(0, space);
            std::string index = line.substr(space + 1, line.size());

            TriCTASSwaps.push_back(stoi(cycle));
            TriCTASIndices.push_back(stoi(index));
        }

        i++;
    }

    return TriCTASSwaps.size();
}